//I, Zeynep Ozcan, certify that these test cases have been generated by Gemini.
import assert from 'node:assert/strict';
import { afterEach, describe, it, mock } from 'node:test';

import { cancelOrder, changeRestaurantStatus, updateOperatorProfile } from '../../app/operator/operatorApi.ts';
import { API_URL, ApiError } from '../../api/client.ts';

function mockFetch(status: number, body: unknown) {
  return mock.method(globalThis, 'fetch', async () => new Response(JSON.stringify(body), { status }));
}

describe('operator api', () => {
  afterEach(() => mock.restoreAll());

  it('cancels an order with a POST and the bearer token', async () => {
    const fetchMock = mockFetch(200, {});
    await cancelOrder(5, 'tok');
    const [url, init] = fetchMock.mock.calls[0].arguments as [string, RequestInit];
    assert.equal(url, `${API_URL}/api/operator/orders/5/cancel`);
    assert.equal(init.method, 'POST');
    assert.equal((init.headers as Record<string, string>).Authorization, 'Bearer tok');
  });

  it('changes a restaurant status with a PUT and the new status', async () => {
    const fetchMock = mockFetch(200, {});
    await changeRestaurantStatus(3, 'paused', 'tok');
    const [url, init] = fetchMock.mock.calls[0].arguments as [string, RequestInit];
    assert.equal(url, `${API_URL}/api/operator/restaurants/3/status`);
    assert.equal(init.method, 'PUT');
    assert.deepEqual(JSON.parse(init.body as string), { status: 'paused' });
  });

  it('turns a 403 from a non-operator into an ApiError', async () => {
    mockFetch(403, { message: 'role:CUSTOMER does not have permission' });
    await assert.rejects(cancelOrder(5, 'tok'), (e: ApiError) => e.status === 403);
  });

  it('turns a 409 into an ApiError carrying the server message', async () => {
    mockFetch(409, { message: 'Restaurant 3 is already paused' });
    await assert.rejects(changeRestaurantStatus(3, 'paused', 'tok'),
      (e: ApiError) => e.status === 409 && e.message === 'Restaurant 3 is already paused');
  });

  it('reports an unreachable server with status 0', async () => {
    mock.method(globalThis, 'fetch', async () => { throw new Error('down'); });
    await assert.rejects(cancelOrder(5, 'tok'), (e: ApiError) => e.status === 0);
  });
});

describe('operator profile api', () => {
  afterEach(() => mock.restoreAll());

  it('sends the current name and changed phone with PATCH and the session token', async () => {
    const updated = { id: 8, name: 'Olivia', email: 'o@demo.test', phone: '5145550199', role: 'OPERATOR' };
    const fetchMock = mockFetch(200, updated);
    const result = await updateOperatorProfile({ name: 'Olivia', phone: '5145550199' }, 'tok');
    const [url, init] = fetchMock.mock.calls[0].arguments as [string, RequestInit];
    assert.equal(url, `${API_URL}/api/profile`);
    assert.equal(init.method, 'PATCH');
    assert.equal((init.headers as Record<string, string>).Authorization, 'Bearer tok');
    assert.deepEqual(JSON.parse(init.body as string), { name: 'Olivia', phone: '5145550199' });
    assert.deepEqual(result, updated);
  });

  it('turns a validation error into an ApiError with the field message', async () => {
    mockFetch(400, { message: 'Validation failed', fieldErrors: { phone: 'must be a valid phone number' } });
    await assert.rejects(updateOperatorProfile({ name: 'Olivia', phone: 'x' }, 'tok'),
      (e: ApiError) => e.status === 400 && e.message === 'must be a valid phone number');
  });
});